def compressir_repeticiones(texto: str) -> str:
    if not texto:
        return ""
    result = []
    i = 0
    n = len(texto)
    while i < n:
        char = texto[i]
        count = 1
        j = i + 1
        while j < n and texto[j] == char:
            count += 1
            j += 1
        result.append(f"{char}{count}")
        i = j
    return "".join(result)

def iniciales(nombre: str) -> str:
    s = nombre.strip()
    if not s:
        return ""
    words = s.split()
    return ''.join(word[0].upper() for word in words)

def es_palindromo(texto: str) -> bool:
    cleaned = ''.join(ch for ch in texto if ch.isalnum()).lower()
    return cleaned == cleaned[::-1]

def aplanar(datos):
    def flatten(obj):
        if isinstance(obj, (list, tuple)):
            result = []
            for elem in obj:
                if isinstance(elem, (list, tuple)):
                    result.extend(flatten(elem))
                else:
                    result.append(elem)
            return result
        else:
            # For non-container objects, keep them as a single-element list.
            return [obj]
    out = []
    for item in datos:
        if isinstance(item, (list, tuple)):
            out.extend(flatten(item))
        else:
            out.append(item)
    return out

def promedio_movil(valores: list[float], ventana: int) -> list[float]:
    if ventana <= 0 or ventana > len(valores):
        return []
    resultado = []
    for i in range(len(valores) - ventana + 1):
        resultado.append(sum(valores[i:i + ventana]) / ventana)
    return resultado
